def sum_of_divisors(n):
    return sum(i for i in range(1, n) if n % i == 0)

a = int(input("Enter first number: "))
b = int(input("Enter second number: "))
if sum_of_divisors(a) == b and sum_of_divisors(b) == a and a != b:
    print(f"{a} and {b} are Amicable numbers")
else:
    print(f"{a} and {b} are not Amicable numbers")

n = int(input("Enter upper limit: "))
is_prime = [True] * (n + 1)
is_prime[0] = is_prime[1] = False
for i in range(2, int(n ** 0.5) + 1):
    if is_prime[i]:
        for multiple in range(i * i, n + 1, i):
            is_prime[multiple] = False
primes = [i for i, prime in enumerate(is_prime) if prime]
print(f"Primes up to {n}: {primes}")

from functools import lru_cache

@lru_cache(maxsize=None)
def fibonacci(n):
    if n <= 1:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

n = int(input("Enter N: "))
print(f"Fibonacci({n}) = {fibonacci(n)}")

limit = int(input("Enter limit: "))
triplets = []
for a in range(1, limit + 1):
    for b in range(a, limit + 1):
        c_squared = a * a + b * b
        c = int(c_squared ** 0.5)
        if c * c == c_squared and c <= limit:
            triplets.append((a, b, c))
print(f"Pythagorean triplets up to {limit}: {triplets}")

