n = int(input("Enter number of rows: "))
triangle = [[1] * (i + 1) for i in range(n)]
for i in range(2, n):
    for j in range(1, i):
        triangle[i][j] = triangle[i - 1][j - 1] + triangle[i - 1][j]
for row in triangle:
    print(' '.join(map(str, row)))

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

n = int(input("Enter N: "))
count, num, total = 0, 2, 0
while count < n:
    if is_prime(num):
        total += num
        count += 1
    num += 1
print(f"Sum of first {n} prime numbers = {total}")
